import{GameState}from'../game/state.js';import{CanvasRenderer}from'../renderer/canvas-renderer.js';import{GestureController}from'../input/gesture.js';import{AudioSystem}from'../audio/audio.js';import{UI}from'../ui/ui.js';import{save}from'../persistence/save.js';import{selfTest}from'../tests/selftest.js';const c=document.querySelector('#game'),g=new GameState(),r=new CanvasRenderer(c),a=new AudioSystem(),u=new UI();let l=false,s='STEALTH',t=performance.now();new GestureController(c,{onPreview:(x,y,d)=>r.setPreview(x,y,d),onSwipe:d=>{if(g.mode!=='play')return;a.unlock();g.shift(d);r.gravityPulse();a.shift()}});function start(){a.unlock();g.start();l=false;s='STEALTH';u.showPlay()}play.onclick=start;retry.onclick=start;function frame(n){const d=Math.min(.033,(n-t)/1000);t=n;if(g.mode==='play'){g.update(d);u.update(g);if(g.security.state!==s){s=g.security.state;a.alarm(s)}if(g.hasLoot&&!l){l=true;a.loot()}if(g.mode==='result'){const z=g.score();save.record(z);a.success();u.showResult(z,g.elapsed,g.shifts,g.security.multiplier())}}r.render(g,d);requestAnimationFrame(frame)}selfTest();requestAnimationFrame(frame);if('serviceWorker'in navigator)addEventListener('load',()=>navigator.serviceWorker.register('./sw.js'));